// Build comma-separated CVE ID list for EPSS bulk API call
const items = $input.all();
const cveIds = items.map(i => i.json.cve_id).filter(Boolean);

return [{ json: { cve_ids: cveIds, cve_list: cveIds.join(','), batch_size: cveIds.length, items: items.map(i => i.json) } }];

// ─── COMPOSITE RISK SCORING ENGINE ──────────────────────────────
// Combines CVSS v3 Base Score + EPSS Probability + Asset Criticality
// to produce a prioritized risk score (0–100) for each vulnerability.

const batchData = $('Build CVE List').first().json;
const epssData = $('Fetch EPSS Scores').first().json;
const nvdData = $('Fetch NVD CVSS v3 Data').first().json;

// Build EPSS lookup map: cve_id → epss_score
const epssMap = {};
if (epssData.data) {
  for (const entry of epssData.data) {
    epssMap[entry.cve] = {
      epss: parseFloat(entry.epss),
      percentile: parseFloat(entry.percentile)
    };
  }
}

// Build NVD lookup map
const nvdMap = {};
if (nvdData.vulnerabilities) {
  for (const v of nvdData.vulnerabilities) {
    const cve = v.cve;
    const metrics = cve.metrics?.cvssMetricV31?.[0] || cve.metrics?.cvssMetricV30?.[0];
    nvdMap[cve.id] = {
      cvss_v3: metrics?.cvssData?.baseScore || null,
      cvss_vector: metrics?.cvssData?.vectorString || null,
      attack_vector: metrics?.cvssData?.attackVector || null,
      privileges_required: metrics?.cvssData?.privilegesRequired || null,
      user_interaction: metrics?.cvssData?.userInteraction || null,
      description: cve.descriptions?.find(d => d.lang === 'en')?.value || 'No description',
      cwe: cve.weaknesses?.[0]?.description?.[0]?.value || null,
      published: cve.published
    };
  }
}

// Score each vulnerability
const scored = batchData.items.map(vuln => {
  const cveId = vuln.cve_id;
  const epss = epssMap[cveId] || { epss: 0, percentile: 0 };
  const nvd = nvdMap[cveId] || {};

  // Use NVD score if available, fall back to stored score
  const cvssScore = nvd.cvss_v3 || vuln.cvss_score || 0;

  // ── Composite Score Formula ────────────────────────────────────
  // CVSS contributes 40%: normalized to 0-100
  const cvssNorm = (cvssScore / 10) * 100;

  // EPSS contributes 45%: probability × 100
  const epssNorm = epss.epss * 100;

  // Asset criticality contributes 15%
  const critMap = { critical: 100, high: 80, medium: 60, low: 40, unknown: 50 };
  const assetCrit = critMap[vuln.asset_criticality?.toLowerCase()] || 50;

  const compositeScore = Math.round(
    (cvssNorm * 0.40) + (epssNorm * 0.45) + (assetCrit * 0.15)
  );

  // ── Priority Tier ──────────────────────────────────────────────
  let priority = 'P4-Low';
  let sla_days = 30;
  if (compositeScore >= 85)      { priority = 'P1-Critical'; sla_days = 1; }
  else if (compositeScore >= 70) { priority = 'P2-High';     sla_days = 7; }
  else if (compositeScore >= 50) { priority = 'P3-Medium';   sla_days = 14; }

  // Check if SLA is already breached
  const daysOpen = vuln.created_at ?
    Math.floor((Date.now() - new Date(vuln.created_at)) / 86400000) : 0;
  const sla_due_date = new Date(Date.now() + sla_days * 86400000).toISOString().split('T')[0];
  const sla_breached = daysOpen > sla_days;

  return {
    ...vuln,
    // Enriched CVSS
    cvss_v3: cvssScore,
    cvss_vector: nvd.cvss_vector || vuln.cvss_vector,
    attack_vector: nvd.attack_vector,
    cwe: nvd.cwe,
    vuln_description: nvd.description || vuln.description,
    nvd_published: nvd.published,
    // EPSS
    epss_score: epss.epss,
    epss_percentile: epss.percentile,
    epss_pct_display: `${(epss.epss * 100).toFixed(2)}%`,
    // Composite scoring
    composite_score: compositeScore,
    priority_tier: priority,
    sla_days,
    sla_due_date,
    days_open: daysOpen,
    sla_breached,
    // Breakdown
    score_breakdown: {
      cvss_contribution: Math.round(cvssNorm * 0.40),
      epss_contribution: Math.round(epssNorm * 0.45),
      asset_contribution: Math.round(assetCrit * 0.15)
    }
  };
});

// Sort by composite score descending
scored.sort((a, b) => b.composite_score - a.composite_score);

// Separate SLA breaches for escalation
const sla_breached = scored.filter(v => v.sla_breached);
const p1_critical = scored.filter(v => v.priority_tier === 'P1-Critical');

return [{
  json: {
    scored_vulns: scored,
    total: scored.length,
    p1_count: p1_critical.length,
    sla_breach_count: sla_breached.length,
    sla_breached_ids: sla_breached.map(v => v.cve_id),
    top_10: scored.slice(0, 10),
    scored_at: new Date().toISOString()
  }
}];

